draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw tank
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.strokeRect(50, 50, W - 100, H - 100);

  // draw fish
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + 50 * Math.sin(t), H / 2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // draw fish tail
  ctx.beginPath();
  ctx.moveTo(W / 2 + 50 * Math.sin(t), H / 2 + 20);
  ctx.lineTo(W / 2 + 50 * Math.sin(t) + 20 * Math.sin(2 * t), H / 2 + 20 + 10 * Math.cos(2 * t));
  ctx.lineWidth = 3;
  ctx.stroke();

  // draw bubbles
  ctx.beginPath();
  ctx.arc(W / 2 + 50 * Math.sin(t), H / 2 - 20 - 10 * Math.sin(3 * t), 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
